declare namespace Bun {
  interface ShellOutput {
    exitCode: number;
    stdout: Uint8Array;
    stderr: Uint8Array;
  }

  interface ShellPromise extends Promise<ShellOutput> {
    quiet(): ShellPromise;
    nothrow(): ShellPromise;
  }

  interface Shell {
    (strings: TemplateStringsArray, ...values: string[]): ShellPromise;
  }

  const $: Shell;
}
